# region: shape
def shape(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: emit
def emit(xs, factor=3):
    return [v * factor for v in xs]

# region: intake
def intake(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': min(xs) if xs else 0}

# region: render
def render(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return render(sift(intake(emit(shape(raw)))))

